export const today=()=>new Date().toLocaleDateString('en-CA');
export const uid=(kind)=>kind+'-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,6);
export function newCard(source='simple',topic='',subtopic=''){return {id:uid('card'),type:'card',source,topic,subtopic,name:subtopic||'',words:'',date:today(),photo:null,art:0,template:0,recording:null,sound:null,mixed:false,voiceVolume:75,soundVolume:30,status:'draft'};}
export function newAlbum(){return {id:uid('album'),type:'album',name:'',description:'',photo:null,art:0,template:0,cardIds:[],snapshots:[],intro:null,date:today(),status:'draft'};}
